package sigepac.poo.infraestructura.persistencia;
import sigepac.poo.dominio.repositorios.IRepositorioDeudaAlquiler;import sigepac.poo.dominio.entidades.*;import sigepac.poo.dominio.objetos_valor.Dinero;import sigepac.poo.infraestructura.ConexionPoo;import java.sql.*;import java.util.*;
/** Adaptador JDBC de agregados de deuda y sus transacciones de pago. */
public class RepositorioDeudaAlquilerJdbc implements IRepositorioDeudaAlquiler {
 private DeudaAlquiler mapD(ResultSet r)throws SQLException{return new DeudaAlquiler(r.getInt("id_deuda"),r.getInt("id_negocio"),r.getString("fecha_inicio"),r.getString("fecha_limite"),new Dinero(r.getBigDecimal("monto_original")),new Dinero(r.getBigDecimal("saldo_actual")),r.getString("estado"),r.getString("nombre_comercial"),r.getString("numero_local"));}
 private static final String SEL="SELECT d.*,n.nombre_comercial,n.numero_local FROM oop_deudas_alquiler d JOIN oop_negocios_comerciales n ON n.id_negocio=d.id_negocio";
 public List<DeudaAlquiler> obtenerTodos(){List<DeudaAlquiler>a=new ArrayList<>();try(Connection c=ConexionPoo.abrir();Statement s=c.createStatement();ResultSet r=s.executeQuery(SEL+" ORDER BY d.id_deuda")){while(r.next())a.add(mapD(r));return a;}catch(SQLException e){throw ConexionPoo.fallo(e);}}
 public List<DeudaAlquiler> obtenerActivosPorNegocio(int id){List<DeudaAlquiler>a=new ArrayList<>();try(Connection c=ConexionPoo.abrir();PreparedStatement p=c.prepareStatement(SEL+" WHERE d.id_negocio=? AND d.saldo_actual>0 ORDER BY d.id_deuda FOR UPDATE")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){while(r.next())a.add(mapD(r));return a;}}catch(SQLException e){throw ConexionPoo.fallo(e);}}
 public int guardarDeuda(DeudaAlquiler d){try(Connection c=ConexionPoo.abrir();PreparedStatement p=c.prepareStatement("INSERT INTO oop_deudas_alquiler(id_negocio,fecha_inicio,fecha_limite,monto_original,saldo_actual,estado) VALUES(?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setInt(1,d.getIdNegocio());p.setDate(2,java.sql.Date.valueOf(d.getFechaInicio()));p.setDate(3,java.sql.Date.valueOf(d.getFechaLimite()));p.setBigDecimal(4,new java.math.BigDecimal(d.getMontoOriginal().getCantidad()));p.setBigDecimal(5,new java.math.BigDecimal(d.getSaldoActual().getCantidad()));p.setString(6,d.getEstado());p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){if(r.next()){d.setIdDeuda(r.getInt(1));return r.getInt(1);}throw new SQLException("Falta id generado");}}catch(SQLException e){throw ConexionPoo.fallo(e);}}
 public boolean actualizarDeuda(DeudaAlquiler d){try(Connection c=ConexionPoo.abrir();PreparedStatement p=c.prepareStatement("UPDATE oop_deudas_alquiler SET saldo_actual=?,estado=? WHERE id_deuda=?")){p.setBigDecimal(1,java.math.BigDecimal.valueOf(d.getSaldoActual().getCantidad()));p.setString(2,d.getEstado());p.setInt(3,d.getIdDeuda());return p.executeUpdate()>0;}catch(SQLException e){throw ConexionPoo.fallo(e);}}
 public int registrarPago(TransaccionPago p){try(Connection c=ConexionPoo.abrir();PreparedStatement s=c.prepareStatement("INSERT INTO oop_transacciones_pago(id_deuda,monto,fecha_registro,metodo_pago) VALUES(?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){s.setInt(1,p.getIdDeuda());s.setBigDecimal(2,java.math.BigDecimal.valueOf(p.getMonto().getCantidad()));s.setTimestamp(3,Timestamp.valueOf(p.getFechaPago().length()==10?p.getFechaPago()+" 00:00:00":p.getFechaPago()));s.setString(4,p.getMetodoPago());s.executeUpdate();try(ResultSet r=s.getGeneratedKeys()){if(r.next()){p.setIdPago(r.getInt(1));return r.getInt(1);}throw new SQLException("Falta id generado");}}catch(SQLException e){throw ConexionPoo.fallo(e);}}
 public List<TransaccionPago> obtenerTodosLosPagos(){List<TransaccionPago>a=new ArrayList<>();String q="SELECT p.*,n.nombre_comercial FROM oop_transacciones_pago p JOIN oop_deudas_alquiler d ON d.id_deuda=p.id_deuda JOIN oop_negocios_comerciales n ON n.id_negocio=d.id_negocio ORDER BY p.id_transaccion DESC";try(Connection c=ConexionPoo.abrir();Statement s=c.createStatement();ResultSet r=s.executeQuery(q)){while(r.next())a.add(new TransaccionPago(r.getInt("id_transaccion"),r.getInt("id_deuda"),new Dinero(r.getBigDecimal("monto")),r.getString("fecha_registro"),r.getString("metodo_pago"),r.getString("nombre_comercial")));return a;}catch(SQLException e){throw ConexionPoo.fallo(e);}}
}
